/* ================= Guide content (from «برنامج وورد — دليل التطبيق العملي» إعداد: سارة حرب) ================= */
const TRIP='<p class="wtitle">رحلتي المدرسية</p><p>'+LOREM+'</p>';
const P1='ذهبنا في رحلة مدرسية إلى مدينة أريحا، وكانت الرحلة رائعة ومليئة بالمعلومات المفيدة.';
const P2='زرنا قصر هشام وتل السلطان، وتعرّفنا إلى تاريخ المدينة القديم وأشجار النخيل.';
const TIMES='font-family:Times New Roman';
const firstP=()=>firstBody().querySelector('p');
const pics=()=>doc.querySelector('.obj.pic');
const shp=k=>doc.querySelector(k?`.obj.shp[data-kind="${k}"]`:'.obj.shp');
const sw=(panel,cmd,i)=>`[data-panel="${panel}"] .ddw.open [data-swcmd],[data-panel="${panel}"] .ddw.open .sw[data-cmd="${cmd}"]:nth-child(${i})`;
const SWI=(cmd,color,say)=>I(`.ddw.open .sw[data-cmd="${cmd}"][data-arg="${color}"]`,say||'اختيار لون');
const isRed=el=>{if(!el)return false;const m=getComputedStyle(el).color.match(/\d+/g).map(Number);return m[0]>150&&m[1]<100&&m[2]<100};
const elText=(root,str)=>{const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode())if(n.nodeValue.includes(str))return n.parentElement;return null};
const DOCX=(html,extra={})=>({html,...extra});
const hfText=k=>{const d=document.createElement('div');d.innerHTML=S.hf[k]||'';d.querySelectorAll('.ph').forEach(x=>x.remove());return d.textContent.trim()};
const typeInput=(sel,text)=>async()=>{const i=$(sel);i.value='';for(const ch of text){i.value+=ch;i.dispatchEvent(new Event('input'));await wait(70)}};
